let t0, batch, nextBatch, rects,
	palette,
	emptyMap,
	candidatePoints,
	maxSize,
	minCurlSz,
	maxCurlSz;

const emptyScale = 0.1;

const palettes = [
	["#900f4c", "#a55a0d", "#8f9b15", "#1cd2ac", "#ace3ff", "#ffffff"],
	["#6c460a", "#577e1d", "#19a79d", "#6ebdfd", "#e2d0ff", "#ffffff"],
	["#275d29", "#147f86", "#4e90f8", "#df91fb", "#ffcacd", "#ffffff"],
	["#0d5968", "#4f59e9", "#e439d8", "#fd9485", "#fed471", "#ffffff"],
	["#5228b5", "#c0168b", "#e86422", "#ccb712", "#44feaa", "#ffffff"]
]

function setup() {
	createCanvas(windowWidth, windowHeight);
	maxSize = max(width, height);
	generate();
}

function generate() {
	palette = random(palettes);
	batch = [];
	nextBatch = [];
	rects = [];
	emptyMap = createGraphics(width,height);
	emptyMap.pixelDensity(1);
	[minCurlSz,maxCurlSz] = [maxSize/200, maxSize/40];
	candidatePoints = [];
	for (let i = 0; i < 10; i++) addToBatchMaybe(batch);
	//print (batch)
	t0 = millis();
	background(0);
}

function harvestCandidates () {
	let [w,h] = [round(width*emptyScale),round(height*emptyScale)]
	let em = createGraphics (w,h);
	em.pixelDensity(1);
	em.drawingContext.imageSmoothingEnabled = false;
	em.image(emptyMap,0,0,width*emptyScale,height*emptyScale);
	em.loadPixels();
	candidatePoints = [];
	let px = em.pixels;
	let n = em.pixels.length;
	for (let i = 0; i < n; i+=4) {
		if (px[i+3] == 0) {
			let k = i/4;
			let x = (k%w+random()) / emptyScale;
			let y = (k/w+random()) / emptyScale;
			candidatePoints.push ([x,y])
		}
	}
	//print (candidatePoints.length);
}

function addToBatchMaybe(batch) {
	var x, y;
	if (candidatePoints.length>0) {
		[x,y] = random(candidatePoints);
	}
	else {
		[x,y] = [random(width), random(height)]
	}
	let curl = randomCurlicue(x,y);
	var k = curl.length;
	if (k < 20) return;

	const k1 = floor(k * 0.4)
	const k2 = floor(k * 0.6)
	const sample = resampleCurve(curl,32);
	const curveRects = [smallestRect(sample.slice(0, 8)),
		smallestRect(sample.slice(8, 16)),
		smallestRect(sample.slice(16, 24)),
		smallestRect(sample.slice(24)),
	];
	const sz = new MBR(...sample).size();
	const wid = map(max(sz.x, sz.y), 0, maxSize / 5, 3, maxSize / 80);
	for (let rect of curveRects) {
		rect.w += wid * 2;
		rect.h += wid * 2;
		rect.recomputeMbr()
	}
	for (let r of rects) {
		for (let g of curveRects)
			if (r.intersectRect(g)) return;
	}
	batch.push({
		pts: refineCurve(curl),
		rects: curveRects,
		sz,
		wid,
		color: random(palette),
	});
	rects.push(...curveRects);
	var em = emptyMap;
	em.fill(255)
	for (let r of curveRects) {
		em.beginShape()
		let {w,h} = r;
		r.w *= 1.4;
		r.h *= 1.4;
		for (let p of r.vertices()) em.vertex(p.x,p.y);
		em.endShape(CLOSE)
		r.w = w;
		r.h = h;
	}
}

function arcLenMeasure(pts) {
	let arcLen = [0];
	let u = [];
	var n = pts.length;
	let totalLen = 0;
	if (n < 2) throw "degenerate curve"
	for (let i = 1; i < n; i++) {
		let [p, q] = pts.slice(i - 1, i + 1);
		let v = createVector(p.x - q.x, p.y - q.y)
		let len = v.mag();
		totalLen += len;
		arcLen[i] = totalLen;
		u[i] = v
	}
	u[0] = u[1];
	return {u,arcLen,totalLen}
}

function resampleCurve(pts,n) {
	let {u, arcLen:per, totalLen:len} = arcLenMeasure(pts);
  let dlen = len / (n - 1);
  let p = pts[0];
  let r = [];
  r.push(p.copy());
  let j = 0;
  for (let i = 1; i < n; i++) {
  	let d = dlen * i;
    while (j + 1 < pts.length - 1 && per[j + 1] < d) j++;
    let rate = per[j + 1] - per[j];
    let alpha = rate == 0 ? 0 : (d - per[j]) / rate;
    let pt = pts[j].copy().lerp(pts[j + 1], alpha);
    r.push(pt);
  }
	return r;
}


function refineCurve(pts, segSize = 1) {
	let result = [];
	result.push(pts[0]);
	for (let i = 1; i < pts.length; i++) {
		let prev = pts[max(0, i - 2)];
		var p = pts[i - 1];
		let q = pts[i];
		let next = pts[min(pts.length - 1, i + 1)]
		var v = p5.Vector.sub(q, p);
		var len = v.mag();
		var n = round(len / segSize);
		for (let j = 1; j <= n; j++) {
			var x = curvePoint(prev.x, p.x, q.x, next.x, j / n)
			var y = curvePoint(prev.y, p.y, q.y, next.y, j / n)
			result.push(createVector(x, y))
		}
	}
	return result;
}

function varWidStroke(pts, {
	start = 0,
	middle = 10,
	end = 0
} = {}) {
	var totalLen = 0;
	var arcLen = [0];
	var u = [createVector(0, 0)];
	var n = pts.length;
	if (n < 4) return [];
	for (let i = 1; i < n; i++) {
		let [p, q] = pts.slice(i - 1, i + 1);
		var v = createVector(p.x - q.x, p.y - q.y)
		var len = v.mag();
		totalLen += len;
		arcLen[i] = totalLen;
		u[i] = v.normalize();
	}
	u[0] = u[1];
	let norm = [];
	for (let i = 0; i < n; i++) {
		var v = p5.Vector.add(u[i], u[min(n - 1, i + 1)]);
		let vmag = v.mag()
		if (vmag > 0.001) {
			v.mult(1 / vmag);
			norm[i] = createVector(-v.y, v.x); // Rotate 90 deg
		} else norm[i] = createVector(0, 0);
	}
	let envelope1 = [],
		envelope2 = [];
	let n1 = floor(n / 2);
	let len1 = arcLen[n1 - 1];
	for (let i = 0; i < n1; i++) {
		var alpha = arcLen[i] / len1;
		var wid = (1 - alpha) * start + alpha * middle;
		let delta = norm[i].copy().mult(wid);
		envelope1.push(pts[i].copy().add(delta));
		envelope2.push(pts[i].copy().sub(delta));
	}
	let len2 = totalLen - len1;
	for (let i = n1; i < n; i++) {
		var alpha = (arcLen[i] - len1) / len2;
		var wid = (1 - alpha) * middle + alpha * end;
		var delta = norm[i].copy().mult(wid);
		envelope1.push(pts[i].copy().add(delta));
		envelope2.push(pts[i].copy().sub(delta));
	}
	return [...envelope1, ...envelope2.reverse()]
}

function curlicuePoints(p, v, dang, rate) {
	let mag = v.mag();
	let maxSteps = 100;
	var result = [];
	p = p.copy();
	v = v.copy();
	while (mag > 1 && maxSteps--) {
		result.push(p.copy());
		p.add(v);
		mag *= rate;
		v.setMag(mag);
		v.rotate(dang)
	}
	return result;
}

function randomCurlicue(x, y) {
	var p = createVector(x, y);
	let vlen = random(minCurlSz,maxCurlSz);
	var v = createVector(vlen, 0);
	let ang = (random(10, 20)) * random([-1, 1]);
	v.rotate(random(TAU))
	var result = curlicuePoints(p, v, radians(ang), random(0.9, 0.95)).reverse();
	if (random() < 0.6) result = result.concat(curlicuePoints(p, v.mult(-1), radians(ang), random(0.9, 0.95)));
	return result;
}

