		} of batch) {
		var n = pts.length;
		var k = (n / 2) * portion;
		let i0 = round(n / 2 - k);
		let i1 = round(n / 2 + k);
		let segment = //curvePoints.slice(i0,i1); 
			pts.slice(0, round(n * portion));
		wid *= portion;
		fill(color);
		noStroke();
		beginShape();
		for (let p of varWidStroke(segment, {
				middle: wid
			})) {
			vertex(p.x, p.y)
		}
		endShape()
		// stroke(200);
