		// 	beginShape()
		// 	for (let p of r.vertices()) vertex(p.x,p.y)
		// 	endShape(CLOSE)
		// }
	}
	if (portion == 1 || batch.length == 0) {
		if (batch.length == 0) {
			maxCurlSz = max(minCurlSz,maxCurlSz*0.8);
		}
		t0 = millis();
