}

// === Tab: Rect ===
class Rect {
	constructor (x,y,w,h,angle) {
		Object.assign(this, {x,y,w,h,angle})
		this.recomputeMbr();
	}
	recomputeMbr() {
		this.mbr = new MBR(...this.vertices());		
	}
	intersectRect(r2) {
		if (this.mbr.intersects(r2.mbr))
			return rectanglesIntersect(this,r2)
		return false;
	}
	vertices() {
		return getRotatedVertices(this)
	}
}


function rectanglesIntersect(rect1, rect2) {
  const vertices1 = getRotatedVertices(rect1);
  const vertices2 = getRotatedVertices(rect2);

  // Check all axes of both rectangles
  const axes = getAxes(vertices1).concat(getAxes(vertices2));
  for (let axis of axes) {
    const projection1 = projectOntoAxis(vertices1, axis);
    const projection2 = projectOntoAxis(vertices2, axis);

    // If projections do not overlap, rectangles do not intersect
    if (projection1[1] < projection2[0] || projection2[1] < projection1[0]) {
      return false;
    }
  }

  // All projections overlap, so rectangles intersect
  return true;
}

function getRotatedVertices(rect) {
  const cx = rect.x;
  const cy = rect.y;
  const w = rect.w / 2; // Half width
  const h = rect.h / 2; // Half height
  const angle = rect.angle;

  // Define the four corners relative to the center
  const corners = [
    createVector(-w, -h),
    createVector(w, -h),
    createVector(w, h),
    createVector(-w, h),
  ];

  // Rotate and translate corners
  return corners.map(corner => {
    var x = corner.x * cos(angle) - corner.y * sin(angle);
    var y = corner.x * sin(angle) + corner.y * cos(angle);
    return createVector(cx + x, cy + y);
  });
}

function getAxes(vertices) {
  var axes = [];
  for (let i = 0; i < vertices.length; i++) {
    const p1 = vertices[i];
    const p2 = vertices[(i + 1) % vertices.length];
    const edge = p2.copy().sub(p1);
    const normal = createVector(-edge.y, edge.x); // Perpendicular vector
    axes.push(normal.normalize());
  }
  return axes;
}

function projectOntoAxis(vertices, axis) {
  let min = axis.dot(vertices[0]);
  let max = min;
  for (let i = 1; i < vertices.length; i++) {
    const projection = axis.dot(vertices[i]);
    min = Math.min(min, projection);
    max = Math.max(max, projection);
  }
  return [min, max];
}

// === Tab: MBR ===
/**
 * Axis aligned bounding box
 **/
class MBR {
  // Minimum Bounding Rectangle

  constructor(...args) {
    // MBR for a variable number of points
    this.min = createVector(Infinity, Infinity);
    this.max = createVector(-Infinity,-Infinity);
    for (let p of args) this.add(p);
  }

	static fromRect(x, y, w, h) {
		// Builds from a rectangle
		let mbr = new MBR();
		mbr.min = createVector(x,y);
		mbr.max = createVector(x+w, y+h);
		return mbr;
	}

  valid() {
    // Whether this is a valid MBR
    return this.min.x <= this.max.x && this.min.y <= this.max.y;
  }

  size() {
    // Size of this box
    return createVector(this.max.x - this.min.x, this.max.y - this.min.y);
  }

  center() {
    // Center of the box
    return this.min.copy().add(this.max).mult(0.5);
  }

  add(p) {
    // Adds a new point to this MBR
    this.min.x = Math.min(p.x, this.min.x);
    this.min.y = Math.min(p.y, this.min.y);
    this.max.x = Math.max(p.x, this.max.x);
    this.max.y = Math.max(p.y, this.max.y);
  }

	containedIn (other) {
		// Whether this mbr contained in other mbr
		return other.min.x <= this.min.x && other.max.x >= this.max.x &&
			other.min.y <= this.min.y && other.max.y >= this.max.y 
	}

  contains(p, r = 0) {
    // Whether MBR contains a point / circle
    return (
      p.x + r >= this.min.x &&
      p.y + r >= this.min.y &&
      p.x - r < this.max.x &&
      p.y - r < this.max.y
    );
  }

  pointDist(p) {
    // Distance from box to point
    let dx = Math.max(this.min.x - p.x, 0, p.x - this.max.x);
    let dy = Math.max(this.min.y - p.y, 0, p.y - this.max.y);
    return Math.sqrt(dx * dx + dy * dy);
  }

  intersects(other) {
    // Whether this MBR intersects another MBR
    let minx = Math.max(other.min.x, this.min.x);
    let maxx = Math.min(other.max.x, this.max.x);
    if (minx >= maxx) return false;
    let miny = Math.max(other.min.y, this.min.y);
    let maxy = Math.min(other.max.y, this.max.y);
    return miny < maxy;
  }

  intersection(other) {
    // Returns intersection with another MBR
    let ret = new MBR();
    ret.min.x = Math.max(other.min.x, this.min.x);
    ret.max.x = Math.min(other.max.x, this.max.x);
    ret.min.y = Math.max(other.min.y, this.min.y);
    ret.max.y = Math.min(other.max.y, this.max.y);
    return ret;
  }

  union(other) {
    // Returns union with another MBR
    var ret = new MBR();
    ret.min.x = Math.min(other.min.x, this.min.x);
    ret.max.x = Math.max(other.max.x, this.max.x);
    ret.min.y = Math.min(other.min.y, this.min.y);
    ret.max.y = Math.max(other.max.y, this.max.y);
    return ret;
  }

}

// === Tab: smallestRect ===
function smallestRect(pts) {
  if (pts.length < 3) {
    throw new Error("At least 3 points are required.");
  }

  // Compute the convex hull
  let hull = computeConvexHull(pts);

  let minArea = Infinity;
  let bestRect = null;

  // Iterate over edges of the convex hull
  for (let i = 0; i < hull.length; i++) {
    var p1 = hull[i];
    var p2 = hull[(i + 1) % hull.length];

    // Compute the edge angle
    let edgeAngle = Math.atan2(p2.y - p1.y, p2.x - p1.x);

    // Rotate points to align with the edge
    let rotatedPoints = pts.map(pt => rotatePoint(pt, -edgeAngle));

    // Find bounding rectangle in aligned space
    let minX = Math.min(...rotatedPoints.map(pt => pt.x));
    let maxX = Math.max(...rotatedPoints.map(pt => pt.x));
    let minY = Math.min(...rotatedPoints.map(pt => pt.y));
    let maxY = Math.max(...rotatedPoints.map(pt => pt.y));

    let width = maxX - minX;
    let height = maxY - minY;
    let area = width * height;

    // Update the smallest rectangle
    if (area < minArea) {
      minArea = area;
      let centerX = (minX + maxX) / 2;
      let centerY = (minY + maxY) / 2;
      let center = rotatePoint({ x: centerX, y: centerY }, edgeAngle);
      bestRect = new Rect(center.x, center.y, width, height, edgeAngle);
    }
  }

  return bestRect;
}

// Rotate a point (px, py) around the origin by angle theta
function rotatePoint(pt, theta) {
  let cosTheta = Math.cos(theta);
  let sinTheta = Math.sin(theta);
  return {
    x: pt.x * cosTheta - pt.y * sinTheta,
    y: pt.x * sinTheta + pt.y * cosTheta
  };
}

// Compute convex hull using the Graham scan algorithm
function computeConvexHull(points) {
  points.sort((a, b) => a.x === b.x ? a.y - b.y : a.x - b.x);

  const cross = (o, a, b) => (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);

  let lower = [];
  for (let pt of points) {
    while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], pt) <= 0) {
      lower.pop();
    }
    lower.push(pt);
  }

  let upper = [];
  for (let i = points.length - 1; i >= 0; i--) {
    var pt = points[i];
    while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], pt) <= 0) {
      upper.pop();
    }
    upper.push(pt);
  }

  upper.pop();
  lower.pop();
  return lower.concat(upper);
}

